"""Export every product, including unresolved comparisons, as CSV and a local review."""
import json,csv,html,re,math,sys
from pathlib import Path
from collections import Counter
from decimal import Decimal, ROUND_FLOOR
sys.stdout.reconfigure(encoding='utf8')
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'docs/pricing-review-2026-10-02';FX=Decimal('1550')
D=json.loads((OUT/'catalog-before.json').read_text(encoding='utf8'))
C={c['product_id']:c for c in D['costs']}
M={r['id']:r for r in json.loads((OUT/'market-candidates.json').read_text(encoding='utf8'))}
S=json.loads((OUT/'supplier-live.json').read_text(encoding='utf8'))
L=json.loads((OUT/'product-supplier-links.json').read_text(encoding='utf8'))
rows=[]
for p in D['products']:
 c=C[p['id']];o=S.get(p['source_url'],{});a=[S[u] for u in L[p['id']] if S[u].get('usd') and not S[u].get('error') and (S[u].get('quantity') is None or S[u]['quantity']>0)]
 alt=min(a,key=lambda x:x['usd']) if a else {}
 usd=Decimal(str(o['usd'])) if not o.get('error') and o.get('usd') else None
 purchase=usd*FX if usd else None
 ml=M[p['id']]['candidates'][0] if M[p['id']]['candidates'] else None
 target=(Decimal(str(ml['price']))*Decimal('.9')/100).to_integral_value(rounding=ROUND_FLOOR)*100 if ml else None
 floor=None
 if purchase is not None:
  fee=Decimal(str(c['payment_fee_percent'] or 0))/100
  floor=(purchase+sum(Decimal(str(c[k] or 0)) for k in ['freight_per_unit','other_landed_cost','variable_cost','minimum_contribution']))/(1-fee)
 reasons=[]
 if purchase is None:reasons.append('falta cotización actual del proveedor vinculado')
 if ml is None:reasons.append('falta comparable ML suficiente')
 if ml and ml['conflicting_indexed_prices']:reasons.append('precios indexados distintos para la misma publicación')
 if target is not None and floor is not None and target<=floor:reasons.append('objetivo no supera compra y gastos registrados')
 if p['sku']=='MYA-KB-052':reasons.append('unidad 30 g en MYA frente a 30 ml en título ML')
 if p['brand'] in ['Total','Wadfow'] and re.search(r'\b(?:20V|42V|12V)\b',p['title']):reasons.append('confirmar baterías, cargador y accesorios del kit equivalente')
 if ml and not ml['pack'] and p['brand'] not in ['Total','Wadfow']:reasons.append('confirmar unidad/pack en ficha ML')
 status='Pendiente' if reasons else 'Propuesta'
 gain=target-purchase if target is not None and purchase is not None else None
 contribution=target*(1-Decimal(str(c['payment_fee_percent'] or 0))/100)-purchase-sum(Decimal(str(c[k] or 0)) for k in ['freight_per_unit','other_landed_cost','variable_cost']) if gain is not None else None
 row=dict(id=p['id'],sku=p['sku'],producto=p['title'],publicado=p['is_active'],precio_actual_ars=p['retail_price'],mayorista_usd=float(usd) if usd is not None else None,cotizacion_ars_usd=1550,compra_ars=float(purchase) if purchase is not None else None,costo_usuario_historico=c['origin_cost'],moneda_costo_historico=c['currency'],fecha_costo_historico=c['verified_at'],menor_oferta_mayorista_usd=alt.get('usd'),menor_oferta_mayorista_url=alt.get('url'),ml_referencia_ars=ml['price'] if ml else None,precio_objetivo_10_ars=float(target) if target is not None else None,precio_propuesto_ars=float(target) if target is not None and status=='Propuesta' else None,diferencia_venta_compra_ars=float(gain) if gain is not None else None,contribucion_gastos_registrados_ars=round(float(contribution),2) if contribution is not None else None,margen_sobre_venta_pct=round(float(gain/target*100),2) if gain is not None and target else None,cambio_precio_ars=float(target)-p['retail_price'] if target is not None else None,gastos_confirmados=c['expenses_confirmed'],estado=status,motivo='; '.join(reasons) if reasons else 'Referencia de búsqueda indexada; revisar vigencia y gastos antes de publicar',url_tienda='https://myaimportaciones.vercel.app/producto/'+p['slug'],url_mayorista=p['source_url'],fecha_mayorista=o.get('checked_at'),titulo_ML=ml['title'] if ml else None,url_ML=ml['url'] if ml else None,evidencia_ML=ml['source'] if ml else None,fecha_consulta_ML='2026-10-02',precio_ML_anterior=c['ml_price'],url_ML_anterior=c['ml_url'],fecha_ML_anterior=c['ml_checked_at'],disponibilidad_mayorista=o.get('quantity',o.get('availability')))
 rows.append(row)
assert len(rows)==214 and len({r['id'] for r in rows})==214
for r in rows:
 if r['precio_objetivo_10_ars'] is not None:assert Decimal(str(r['precio_objetivo_10_ars']))<=Decimal(str(r['ml_referencia_ars']))*Decimal('.9')
 if r['precio_propuesto_ars'] is not None:assert r['precio_propuesto_ars']>r['compra_ars']
with (OUT/'productos.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(rows[0]),delimiter=';');w.writeheader();w.writerows(rows)
(OUT/'productos.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf8')
summary=dict(fecha='2026-10-02',total=len(rows),publicados=sum(r['publicado'] for r in rows),borradores=sum(not r['publicado'] for r in rows),mayorista_actual=sum(r['compra_ars'] is not None for r in rows),referencia_ML=sum(r['ml_referencia_ars'] is not None for r in rows),propuestas=sum(r['estado']=='Propuesta' for r in rows),propuestas_publicados=sum(r['estado']=='Propuesta' and r['publicado'] for r in rows),pendientes=sum(r['estado']=='Pendiente' for r in rows),sin_ML=sum(r['ml_referencia_ars'] is None for r in rows),objetivo_no_cubre_compra=sum('no supera' in r['motivo'] for r in rows),propuestas_subas=sum(r['estado']=='Propuesta' and r['publicado'] and r['cambio_precio_ars']>0 for r in rows),propuestas_bajas=sum(r['estado']=='Propuesta' and r['publicado'] and r['cambio_precio_ars']<0 for r in rows),cotizacion=1550,descuento_ML=10,precios_modificados_en_tienda=0,nota='Referencias ML indexadas consultadas hoy, pueden estar desactualizadas; no representan el mínimo absoluto del mercado. Ganancia neta no confirmada. Propuestas sin publicar.')
(OUT/'resumen.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf8')
def money(v):return '—' if v is None else '$ '+f'{v:,.2f}'.replace(',','@').replace('.',',').replace('@','.')
e=lambda s:html.escape(str(s or ''),quote=True)
body=[]
for r in rows:
 body.append(f'<tr data-state="{r["estado"]}" data-active="{int(r["publicado"])}"><td><a href="{e(r["url_tienda"])}" target="_blank" rel="noreferrer">{e(r["producto"])}</a><small>{e(r["sku"])} · {"Publicado" if r["publicado"] else "Borrador"}</small></td><td>{money(r["precio_actual_ars"])}</td><td><a href="{e(r["url_mayorista"])}" target="_blank" rel="noreferrer">{("USD "+str(r["mayorista_usd"])) if r["mayorista_usd"] else "Sin precio"}</a><small>Compra: {money(r["compra_ars"])}<br>Alternativa: USD {r["menor_oferta_mayorista_usd"] or "—"}</small></td><td>{("<a target=_blank rel=noreferrer href="+chr(34)+e(r["url_ML"])+chr(34)+">"+money(r["ml_referencia_ars"])+"</a>") if r["url_ML"] else "—"}<small>Referencia indexada</small></td><td><b>{money(r["precio_objetivo_10_ars"])}</b><small>Cambio: {money(r["cambio_precio_ars"])}</small></td><td>{money(r["diferencia_venta_compra_ars"])}<small>Antes de gastos</small></td><td><span class="badge {r["estado"]}">{r["estado"]}</span><small>{e(r["motivo"])}</small></td></tr>')
page='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MYA · Revisión de precios 02/10/2026</title><style>body{margin:28px;background:#f5f7f6;color:#203d30;font:15px system-ui}h1{margin-bottom:8px}p{max-width:1100px;line-height:1.6}.stats{display:flex;gap:12px;flex-wrap:wrap}.stats div{background:white;border:1px solid #dce5df;border-radius:10px;padding:16px}.stats b{font-size:25px;display:block}.controls{display:flex;gap:12px;margin:20px 0;flex-wrap:wrap}input,select{font:inherit;padding:10px;border:1px solid #becfc3;border-radius:6px}input{min-width:280px}table{border-collapse:collapse;background:white;width:100%}th,td{text-align:left;padding:13px;border-bottom:1px solid #e0e7e2;vertical-align:top}th{background:#e5eee8;position:sticky;top:0}td:first-child{min-width:260px}small{display:block;color:#5d6f63;font-size:12px;line-height:1.5;margin-top:5px}a{color:#17724c}.badge{display:inline-block;border-radius:6px;padding:4px 8px;font-size:12px}.Propuesta{background:#dbefdf}.Pendiente{background:#fff0ce}.table{overflow:auto}td:not(:first-child){min-width:130px}td:last-child{min-width:230px}</style><h1>MYA · Precios competitivos con margen</h1><p>Revisión del 02/10/2026. Criterio elegido: <b>10% por debajo de una referencia equivalente de Mercado Libre</b>, redondeado hacia abajo a $100. Cotización de trabajo indicada por el dueño: <b>$1.550/USD</b>. La diferencia venta−compra es el dinero disponible antes de flete, impuestos, comisiones y otros gastos. Los costos del proveedor y sus cantidades son información interna.</p><p><b>Propuestas sin publicar.</b> Mercado Libre se consultó mediante búsqueda web: son precios indexados y pueden tener demora. No se certifica el mínimo absoluto del mercado ni la vigencia en checkout. Los objetivos con un problema de costo, presentación, pack, accesorios o precio contradictorio se señalan como pendientes. Los 45 borradores conservan su estado.</p><div class="stats">'''+''.join(f'<div><b>{summary[k]}</b>{label}</div>' for k,label in [('total','Productos revisados'),('publicados','Publicados'),('mayorista_actual','Con costo actual'),('referencia_ML','Con candidato ML'),('propuestas_publicados','Propuestas para publicados'),('pendientes','Pendientes')])+'''</div><div class="controls"><input id="q" aria-label="Buscar producto" placeholder="Buscar nombre o SKU"><select id="state" aria-label="Estado de comparación"><option value="">Todos los estados</option><option>Propuesta</option><option>Pendiente</option></select><select id="active" aria-label="Publicación"><option value="">Todo el catálogo</option><option value="1">Publicados</option><option value="0">Borradores</option></select><span id="count"></span></div><div class="table"><table><thead><tr><th>Producto</th><th>MYA actual</th><th>Mayorista actual</th><th>Mercado Libre</th><th>Objetivo −10%</th><th>Venta−compra</th><th>Resultado</th></tr></thead><tbody>'''+''.join(body)+'''</tbody></table></div><p>Descargar: <a href="productos.csv">CSV con todos los productos y fuentes</a>. Las referencias anteriores se conservan en el CSV, sin convertirlas en verificaciones actuales. No se modificaron costos, precios, disponibilidad, pedidos ni publicaciones en producción.</p><script>const rows=[...document.querySelectorAll('tbody tr')];function filter(){let n=0;for(const r of rows){r.hidden=!(r.textContent.toLowerCase().includes(document.getElementById('q').value.toLowerCase())&&(!state.value||r.dataset.state===state.value)&&(!active.value||r.dataset.active===active.value));if(!r.hidden)n++}document.getElementById('count').textContent=n+' productos visibles'}const state=document.getElementById('state'),active=document.getElementById('active');for(const id of ['q','state','active'])document.getElementById(id).addEventListener('input',filter);filter();</script></html>'''
(OUT/'revision.html').write_text(page,encoding='utf8')
print(json.dumps(summary,ensure_ascii=False));print('Jelly Cream',next(r for r in rows if r['sku']=='MYA-KB-081'))
